--
-- Table structure for table `descansos`
--

DROP TABLE IF EXISTS `descansos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `descansos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `instructora_id` int NOT NULL,
  `fecha_inicio` date DEFAULT NULL COMMENT 'Fecha de inicio del descanso (NULL para descansos recurrentes)',
