--
-- Table structure for table `usuarios`
--

DROP TABLE IF EXISTS `usuarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `nombre` varchar(100) DEFAULT NULL,
  `apellido` varchar(100) DEFAULT NULL,
  `edad` int DEFAULT NULL,
  `correo` varchar(100) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `contrasena` varchar(255) DEFAULT NULL,
  `rol` enum('administrador','instructora','cliente','creadorcuentas') DEFAULT 'cliente',
  `tipo_cliente` enum('propietario','demo','general','renta','media_renta') DEFAULT NULL,
  `nivel` varchar(50) DEFAULT NULL,
  `tipo_nivel` enum('paseo','iniciacion','intermedio','avanzado') DEFAULT NULL,
  `estatus` enum('activo','inactivo','bloqueado') DEFAULT 'activo',
  `fecha_registro` datetime DEFAULT CURRENT_TIMESTAMP,
  `dia_corte` int DEFAULT '1' COMMENT 'Día del mes para corte (1-28)',
  `ultimo_pago` date DEFAULT NULL COMMENT 'Última fecha de pago registrada',
  `proxima_alerta` date DEFAULT NULL COMMENT 'Próxima fecha sugerida para recordar pago',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_usuarios_dia_corte` (`dia_corte`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

